SELECT @clinic_id AS clinic_id;
SELECT COUNT(*) AS services, SUM(is_price_outdated) AS outdated, SUM(price) AS price_sum  -- expect 2199, 0, 4286263.11
FROM clinic_medical_services WHERE clinic_id = @clinic_id;
SELECT COUNT(*) AS lab_tests, SUM(is_price_outdated) AS outdated, SUM(price) AS price_sum  -- expect 658, 0, 25101.48
